export function c017(context is Context, id is Id)
{
    const arcSketch = newSketchOnPlane(context, id + "arcSketch", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skArc(arcSketch, "arc1", { "start" : vector(20, 0) * millimeter, "mid" : vector(14.142136, 14.142136) * millimeter, "end" : vector(0, 20) * millimeter });
    skSolve(arcSketch);
    extrude(context, id + "sheet", { "bodyType" : ExtendedToolBodyType.SURFACE, "surfaceEntities" : qOwnedByBody(qBodyType(qCreatedBy(id + "arcSketch", EntityType.BODY), BodyType.WIRE), EntityType.EDGE), "endBound" : BoundingType.BLIND, "depth" : 20 * millimeter });
    thicken(context, id + "thicken1", { "entities" : qCreatedBy(id + "sheet", EntityType.BODY), "thickness1" : 1 * millimeter, "thickness2" : 2 * millimeter });
}

// thicken: a sphere of radius 10's face thickened 2 mm outwards
export function c018(context is Context, id is Id)
{
    opSphere(context, id + "base", { "center" : vector(0, 0, 0) * millimeter, "radius" : 10 * millimeter });
    thicken(context, id + "thicken1", { "entities" : qOwnedByBody(qBodyType(qCreatedBy(id + "base", EntityType.BODY), BodyType.SOLID), EntityType.FACE), "thickness1" : 2 * millimeter, "thickness2" : 0 * millimeter });
}

// split-part: a cylinder (radius 10, 20 tall) split by a plane through its axis
export function c019(context is Context, id is Id)
{
    const baseSketch = newSketchOnPlane(context, id + "baseSketch", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skCircle(baseSketch, "circle1", { "center" : vector(0, 0) * millimeter, "radius" : 10 * millimeter });
    skSolve(baseSketch);
    extrude(context, id + "base", { "entities" : qSketchRegion(id + "baseSketch"), "endBound" : BoundingType.BLIND, "depth" : 20 * millimeter });
    opPlane(context, id + "cut", { "plane" : plane(vector(0, 0, 0) * millimeter, vector(1, 1, 0), vector(0, 0, 1)), "width" : 100 * millimeter, "height" : 100 * millimeter });
    splitPart(context, id + "split1", { "targets" : qBodyType(qCreatedBy(id + "base", EntityType.BODY), BodyType.SOLID), "tool" : qCreatedBy(id + "cut", EntityType.FACE) });
}

// split-part: a sphere of radius 10 split by a plane 4 mm off its centre, keeping the front
export function c020(context is Context, id is Id)
{
    opSphere(context, id + "base", { "center" : vector(0, 0, 0) * millimeter, "radius" : 10 * millimeter });
    opPlane(context, id + "cut", { "plane" : plane(vector(0, 0, 4) * millimeter, vector(0, 0, 1), vector(1, 0, 0)), "width" : 100 * millimeter, "height" : 100 * millimeter });
    splitPart(context, id + "split1", { "targets" : qBodyType(qCreatedBy(id + "base", EntityType.BODY), BodyType.SOLID), "tool" : qCreatedBy(id + "cut", EntityType.FACE), "keepBothSides" : false, "keepFront" : true });
}
